              </Row>
            </Column>
          </TabPanel>

          <TabPanel value="notifications" fillWidth gap="8">
            <Heading as="h2" variant="heading-strong-l" paddingBottom="8">
              Notifications
            </Heading>
            <SettingGroup
              label="Email digest"
              info="One summary email instead of a message for every event."
              control={
